class TestFailureStrategyInit:
    """测试 FailureStrategy 初始化"""

    def test_init_with_empty_config(self):
        """正常用例：使用空配置初始化"""
        strategy = FailureStrategy()
        assert strategy.config == {}

    def test_init_with_none_config(self):
        """正常用例：使用 None 配置初始化"""
        strategy = FailureStrategy(None)
        assert strategy.config == {}

    def test_init_with_valid_config(self):
        """正常用例：使用有效配置初始化"""
        config = {
            "failure_strategy": {
                "fallback_enabled": False,
                "fallback_timeout": 10,
                "fallback_max_retries": 5,
                "fallback_on_errors": ["timeout"],
                "degradation_enabled": False,
                "degradation_level": "low",
            }
        }
        strategy = FailureStrategy(config)
        assert strategy.fallback_enabled is False
        assert strategy.fallback_timeout == 10
        assert strategy.fallback_max_retries == 5
        assert strategy.fallback_on_errors == ["timeout"]
        assert strategy.degradation_enabled is False
        assert strategy.degradation_level == "low"


class TestFallbackStrategy:
    """测试默认值回退策略"""

    def test_fallback_enabled_default(self):
        """边界用例：fallback_enabled 默认值为 True"""
        strategy = FailureStrategy()
        assert strategy.fallback_enabled is True

