class TestConfigMerging:
    """测试配置合并功能"""

    def test_partial_config_merges_with_defaults(self):
        """正常用例：部分配置与默认配置合并"""
        config = {
            "failure_strategy": {
                "fallback_enabled": False,
                "degradation_level": "low"
            }
        }
        strategy = FailureStrategy(config)
        # 自定义值
        assert strategy.fallback_enabled is False
        assert strategy.degradation_level == "low"
        # 默认值
        assert strategy.fallback_timeout == 5
        assert strategy.fallback_max_retries == 3
        assert strategy.degradation_enabled is True

    def test_empty_failure_strategy_key(self):
        """异常用例：配置中 failure_strategy 为空字典"""
        config = {"failure_strategy": {}}
        strategy = FailureStrategy(config)
        assert strategy.fallback_enabled is True
        assert strategy.degradation_enabled is True

    def test_missing_failure_strategy_key(self):
        """异常用例：配置中缺少 failure_strategy 键"""
        config = {"other_key": "value"}
        strategy = FailureStrategy(config)
        assert strategy.fallback_enabled is True
        assert strategy.degradation_enabled is True


class TestEdgeCases:
