        config = {
            "failure_strategy": {
                "fallback_enabled": None,
                "fallback_timeout": None,
                "degradation_level": None
            }
        }
        strategy = FailureStrategy(config)
        assert strategy.fallback_enabled is None
        assert strategy.fallback_timeout is None
        assert strategy.degradation_level is None

    def test_config_with_special_types(self):
        """异常用例：配置值为特殊类型"""
        config = {
            "failure_strategy": {
                "fallback_timeout": 3.14,
                "fallback_max_retries": True,
